let field: Uint8Array | null = null;
/** 256 × 256 thresholds 1..255, row-major. */
export function dissolveField(): Uint8Array {
  if (!field) {
    const s = atob(B64);
    field = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) field[i] = s.charCodeAt(i);
  }
  return field;
}
